from solution import zigzag


def test_issue_example_4_3():
    """Issue example: zigzag(4, 3) == 5."""
    assert zigzag(4, 3) == 5  # E(4,3)=E(4,2)+E(3,1)=4+1=5


def test_issue_base_0_0():
    """Entringer base case e(0, 0) is 1."""
    assert zigzag(0, 0) == 1  # E(0,0)=1 base case


def test_issue_single_1_1():
    """Entringer number e(1, 1) is 1."""
    assert zigzag(1, 1) == 1  # E(1,1)=E(1,0)+E(0,0)=0+1=1


def test_issue_small_2_2():
    """Entringer number e(2, 2) is 1."""
    assert zigzag(2, 2) == 1  # E(2,2)=E(2,1)+E(1,0)=1+0=1


def test_issue_small_3_2():
    """Entringer number e(3, 2) is 2."""
    assert zigzag(3, 2) == 2  # E(3,2)=E(3,1)+E(2,1)=1+1=2


def test_issue_middle_4_2():
    """Entringer number e(4, 2) is 4."""
    assert zigzag(4, 2) == 4  # E(4,2)=E(4,1)+E(3,2)=2+2=4


def test_issue_middle_5_3():
    """Entringer number e(5, 3) is 14."""
    assert zigzag(5, 3) == 14  # E(5,3)=E(5,2)+E(4,2)=10+4=14


def test_issue_large_6_2():
    """Entringer number e(6, 2) is 32."""
    assert zigzag(6, 2) == 32  # E(6,2)=E(6,1)+E(5,4)=16+16=32


def test_contract_zero_column():
    """Entringer rule E(n, 0) is 0 for n > 0."""
    assert zigzag(4, 0) == 0  # E(4,0)=0 for n>0 by definition


def test_contract_diagonal_5_5():
    """Entringer diagonal e(5, 5) equals Euler zigzag 16."""
    assert zigzag(5, 5) == 16  # E(5,5)=E(5,4)+E(4,0)=16+0=16


def test_contract_diagonal_6_6():
    """Entringer diagonal e(6, 6) equals Euler zigzag 61."""
    assert zigzag(6, 6) == 61  # E(6,6)=E(6,5)+E(5,0)=61+0=61


def test_contract_row_sum_3():
    """Entringer row n=3 sums to Euler number 5."""
    assert zigzag(3, 0) + zigzag(3, 1) + zigzag(3, 2) + zigzag(3, 3) == 5  # 0+1+2+2=5
